import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validators?: WeakMap<object, ValidateFunction>;
}

const ajv = new Ajv({strict: false, validateFormats: false, coerceTypes: false, useDefaults: false});

function validationMessage(errors: ErrorObject[]): string {
  const error = errors[0];
  if (!error) return 'Input failed schema validation';

  const path =
    error.instancePath || (typeof error.params.missingProperty === 'string' ? `/${error.params.missingProperty}` : '/');
  if (error.keyword === 'required') return `Input validation failed at ${path}: property is required`;
  if (error.keyword === 'type') return `Input validation failed at ${path}: must be ${String(error.params.type)}`;
  return `Input validation failed at ${path}: ${error.message ?? 'schema constraint failed'}`;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validators: typeof definition === 'function' ? new WeakMap<object, ValidateFunction>() : undefined,
    });
  }

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return ajv.compile(definition.inputSchema);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid input schema for tool ${definition.name}: ${message}`);
    }
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) return tool.validator;

    const cached = tool.validators?.get(definition.inputSchema);
    if (cached) return cached;

    const validator = this.compile(definition);
    tool.validators?.set(definition.inputSchema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input and returns rejections; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(tool, definition);
    if (!validator(input)) {
      const result = validationMessage(validator.errors ?? []);
      log.warn('tool', 'input rejected', {name, result});
      return {result};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: returns a required-property rejection without invoking the executor](../../src/orchestration/tools/registry.test.ts#L4), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
export interface Logger {
  debug(category: string, message: string, fields?: Record<string, unknown>): void;
  info(category: string, message: string, fields?: Record<string, unknown>): void;
  warn(category: string, message: string, fields?: Record<string, unknown>): void;
  error(category: string, message: string, fields?: Record<string, unknown>): void;
}

const LOG_LEVELS = {DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3} as const;
type LevelName = keyof typeof LOG_LEVELS;

const METHODS = {DEBUG: 'debug', INFO: 'info', WARN: 'warn', ERROR: 'error'} as const;

const resolvedLevel = (() => {
  const env = (process.env.LOG_LEVEL || 'info').toUpperCase();
  return LOG_LEVELS[env as LevelName] ?? LOG_LEVELS.INFO;
})();

export const UNSERIALISABLE = '[unserialisable]';

function emit(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
  // Caller fields are nested under `data`, so one named `severity` cannot overwrite the line's own.
  const line = {
    severity: level,
    message,
    timestamp: new Date().toISOString(),
    category,
    ...(fields ? {data: fields} : {}),
  };

  // ERROR to stderr: a stream that cannot be split by severity cannot be alerted on.
  // eslint-disable-next-line no-console -- the one place this package writes to a stream
  (level === 'ERROR' ? console.error : console.log)(serialise(line));
}

// A throw here would take down the call site being observed, so an unserialisable field costs that field alone.
function serialise(line: Record<string, unknown>): string {
  const whole = probe(() => JSON.stringify(line));
  if (whole.ok) return whole.value;

  // String() runs the caller's toString, so it is attempted inside the probe rather than before it.
  const degraded = probe(() =>
    JSON.stringify({
      severity: line.severity,
      message: String(line.message),
      timestamp: line.timestamp,
      category: String(line.category),
      data: `${UNSERIALISABLE}: ${whole.reason}`,
    })
  );
  if (degraded.ok) return degraded.value;

  // Nothing the caller supplied survives into this one, so it cannot fail in turn.
  return JSON.stringify({
    severity: line.severity,
    message: UNSERIALISABLE,
    timestamp: line.timestamp,
    category: UNSERIALISABLE,
    data: `${UNSERIALISABLE}: ${degraded.reason}`,
  });
}

// A probe, not control flow: it reports what happened rather than branching on a swallowed error.
function probe(run: () => string): {ok: true; value: string} | {ok: false; reason: string} {
  try {
    return {ok: true, value: run()};
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return {ok: false, reason: reason.split('\n')[0]};
  }
}

const consoleLogger: Logger = {
  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('DEBUG', category, message, fields),
  info: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('INFO', category, message, fields),
  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('WARN', category, message, fields),
  error: (category: string, message: string, fields?: Record<string, unknown>) =>
    emit('ERROR', category, message, fields),
};

let active: Logger = consoleLogger;

// Process-global by design: every module that logs imports `log` at module scope, so there is one.
export function setLogger(logger?: Logger): void {
  // Handed `log` itself, the delegate below would call itself until the stack ran out, so that reads as none.
  active = logger === undefined || logger === log ? consoleLogger : logger;
}

// The one place a level is tested, so LOG_LEVEL gates a supplied logger exactly as it gates the built-in one.
function dispatch(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
  if (LOG_LEVELS[level] < resolvedLevel) return;

  const delivered = probe(() => {
    active[METHODS[level]](category, message, fields);
    return '';
