  1	import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
  2	import type {ToolDefinition} from '../../types/ai.js';
  3	import type {OutgoingMessage} from '../../types/messages.js';
  4	import {log} from '../../shared/logger.js';
  5	
  6	export interface ToolResponse {
  7	  result: string;
  8	  clientMessages?: OutgoingMessage[];
  9	  suppressAssistantResponse?: boolean;
 10	}
 11	
 12	export interface ToolContext {
 13	  userId: string | number;
 14	  sessionId?: string;
 15	  workspaceId?: string | number;
 16	  authHeaders?: {
 17	    cookie?: string;
 18	    authorization?: string;
 19	    host?: string;
 20	  };
 21	}
 22	
 23	export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
 24	
 25	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
 26	  return typeof response === 'string' ? {result: response} : response;
 27	}
 28	
 29	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
 30	
 31	export interface RegisteredTool {
 32	  definition: ToolDefinition;
 33	  execute: ToolExecutor;
 34	}
 35	
 36	interface StoredTool {
 37	  definitionSource: ToolDefinitionSource;
 38	  execute: ToolExecutor;
 39	  validator?: ValidateFunction;
 40	  validators?: WeakMap<object, ValidateFunction>;
 41	}
 42	
 43	const ajv = new Ajv({strict: false, validateFormats: false, coerceTypes: false, useDefaults: false});
 44	
 45	function validationMessage(errors: ErrorObject[]): string {
 46	  const error = errors[0];
 47	  if (!error) return 'Input failed schema validation';
 48	
 49	  const path =
 50	    error.instancePath || (typeof error.params.missingProperty === 'string' ? `/${error.params.missingProperty}` : '/');
 51	  if (error.keyword === 'required') return `Input validation failed at ${path}: property is required`;
 52	  if (error.keyword === 'type') return `Input validation failed at ${path}: must be ${String(error.params.type)}`;
 53	  return `Input validation failed at ${path}: ${error.message ?? 'schema constraint failed'}`;
 54	}
 55	
 56	export class ToolRegistry {
 57	  private readonly tools = new Map<string, StoredTool>();
 58	
 59	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
 60	    return typeof source === 'function' ? source() : source;
 61	  }
 62	
 63	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
 64	    const resolved = this.resolveDefinition(definition);
 65	    const validator = typeof definition === 'function' ? undefined : this.compile(resolved);
 66	    this.tools.set(resolved.name, {
 67	      definitionSource: definition,
 68	      execute,
 69	      validator,
 70	      validators: typeof definition === 'function' ? new WeakMap<object, ValidateFunction>() : undefined,
 71	    });
 72	  }
 73	
 74	  private compile(definition: ToolDefinition): ValidateFunction {
 75	    try {
 76	      return ajv.compile(definition.inputSchema);
 77	    } catch (error) {
 78	      const message = error instanceof Error ? error.message : String(error);
 79	      throw new Error(`Invalid input schema for tool ${definition.name}: ${message}`);
 80	    }
 81	  }
 82	
 83	  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
 84	    if (tool.validator) return tool.validator;
 85	
 86	    const cached = tool.validators?.get(definition.inputSchema);
 87	    if (cached) return cached;
 88	
 89	    const validator = this.compile(definition);
 90	    tool.validators?.set(definition.inputSchema, validator);
 91	    return validator;
 92	  }
 93	
 94	  get(name: string): RegisteredTool | undefined {
 95	    const tool = this.tools.get(name);
 96	    if (!tool) return undefined;
 97	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
 98	  }
 99	
100	  getDefinitions(): ToolDefinition[] {
101	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
102	  }
103	
104	  getPromptInstructions(): string[] {
105	    return this.getDefinitions()
106	      .filter(t => t.promptInstructions)
107	      .map(t => `${t.name}: ${t.promptInstructions}`);
108	  }
109	
110	  getExamplePrompts(): string[] {
111	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
112	  }
113	
114	  has(name: string): boolean {
115	    return this.tools.has(name);
116	  }
117	
118	  /** Validates tool input and returns rejections; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
119	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
120	    const tool = this.tools.get(name);
121	    if (!tool) {
122	      log.warn('tool', 'tool not found', {name});
123	      throw new Error(`Unknown tool: ${name}`);
124	    }
125	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
126	    const definition = this.resolveDefinition(tool.definitionSource);
127	    const validator = this.validatorFor(tool, definition);
128	    if (!validator(input)) {
129	      const result = validationMessage(validator.errors ?? []);
130	      log.warn('tool', 'input rejected', {name, result});
131	      return {result};
132	    }
133	    const rawResult = await tool.execute(input, context);
134	    const response = normalizeToolResponse(rawResult);
135	    log.info('tool', 'execution complete', {
136	      name,
137	      rawType: typeof rawResult,
138	      clientMessageCount: response.clientMessages?.length ?? 0,
139	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
140	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
141	    });
142	    return response;
143	  }
144	}

